/**
 * Stage 1 — Neon City.
 *
 * Buildings are the existing hand-drawn `*_none_*` strips. The lit windows are separate
 * overlay images generated by scripts/generate-city-lights.js, stacked on top at the
 * current light level, so rooms come on through the night and go off again towards dawn.
 *
 * The overlays are cumulative (level 3 already contains levels 0-2), so a tile costs the
 * base image plus at most two overlays — not one draw per window, which is what made the
 * original city lag.
 *
 * Same shape as MidnightMountainsBackground: numbers in, strips tiled by world position.
 */

import { Image } from "@shopify/react-native-skia";
import type { SkImage } from "@shopify/react-native-skia";
import React, { useEffect, useRef } from "react";
import { GROUND_HEIGHT, SCREEN_HEIGHT, SCREEN_WIDTH } from "../../game/constants";
import { useStripImages } from "./useStripImages";

const GRID_TOP_Y = SCREEN_HEIGHT - GROUND_HEIGHT;

/** Number of lighting steps the generator produced. */
const LEVELS = 6;
const VARIANTS = 4;

/** Matches the previous city layout exactly, so stage 1 looks the same. */
const FRONT_HEIGHT = GRID_TOP_Y * 0.53;
const FRONT_WIDTH = FRONT_HEIGHT * (450 / 350);
const BACK_HEIGHT = FRONT_HEIGHT * 1.25;
const BACK_WIDTH = BACK_HEIGHT * (300 / 350);
const FRONT_RATE = 0.5;
const BACK_RATE = 0.2;

const FRONT_BASE = [
    require("../../../assets/city/front_none_1.png"),
    require("../../../assets/city/front_none_2.png"),
    require("../../../assets/city/front_none_3.png"),
    require("../../../assets/city/front_none_4.png"),
];
const BACK_BASE = [
    require("../../../assets/city/back_none_1.png"),
    require("../../../assets/city/back_none_2.png"),
    require("../../../assets/city/back_none_3.png"),
    require("../../../assets/city/back_none_4.png"),
];

// Flattened as variant * LEVELS + level, so one load covers every combination.
const FRONT_LIT = [
    require("../../../assets/city/lights/front_1_lit_0.png"), require("../../../assets/city/lights/front_1_lit_1.png"),
    require("../../../assets/city/lights/front_1_lit_2.png"), require("../../../assets/city/lights/front_1_lit_3.png"),
    require("../../../assets/city/lights/front_1_lit_4.png"), require("../../../assets/city/lights/front_1_lit_5.png"),
    require("../../../assets/city/lights/front_2_lit_0.png"), require("../../../assets/city/lights/front_2_lit_1.png"),
    require("../../../assets/city/lights/front_2_lit_2.png"), require("../../../assets/city/lights/front_2_lit_3.png"),
    require("../../../assets/city/lights/front_2_lit_4.png"), require("../../../assets/city/lights/front_2_lit_5.png"),
    require("../../../assets/city/lights/front_3_lit_0.png"), require("../../../assets/city/lights/front_3_lit_1.png"),
    require("../../../assets/city/lights/front_3_lit_2.png"), require("../../../assets/city/lights/front_3_lit_3.png"),
    require("../../../assets/city/lights/front_3_lit_4.png"), require("../../../assets/city/lights/front_3_lit_5.png"),
    require("../../../assets/city/lights/front_4_lit_0.png"), require("../../../assets/city/lights/front_4_lit_1.png"),
    require("../../../assets/city/lights/front_4_lit_2.png"), require("../../../assets/city/lights/front_4_lit_3.png"),
    require("../../../assets/city/lights/front_4_lit_4.png"), require("../../../assets/city/lights/front_4_lit_5.png"),
];
const BACK_LIT = [
    require("../../../assets/city/lights/back_1_lit_0.png"), require("../../../assets/city/lights/back_1_lit_1.png"),
    require("../../../assets/city/lights/back_1_lit_2.png"), require("../../../assets/city/lights/back_1_lit_3.png"),
    require("../../../assets/city/lights/back_1_lit_4.png"), require("../../../assets/city/lights/back_1_lit_5.png"),
    require("../../../assets/city/lights/back_2_lit_0.png"), require("../../../assets/city/lights/back_2_lit_1.png"),
    require("../../../assets/city/lights/back_2_lit_2.png"), require("../../../assets/city/lights/back_2_lit_3.png"),
    require("../../../assets/city/lights/back_2_lit_4.png"), require("../../../assets/city/lights/back_2_lit_5.png"),
    require("../../../assets/city/lights/back_3_lit_0.png"), require("../../../assets/city/lights/back_3_lit_1.png"),
    require("../../../assets/city/lights/back_3_lit_2.png"), require("../../../assets/city/lights/back_3_lit_3.png"),
    require("../../../assets/city/lights/back_3_lit_4.png"), require("../../../assets/city/lights/back_3_lit_5.png"),
    require("../../../assets/city/lights/back_4_lit_0.png"), require("../../../assets/city/lights/back_4_lit_1.png"),
    require("../../../assets/city/lights/back_4_lit_2.png"), require("../../../assets/city/lights/back_4_lit_3.png"),
    require("../../../assets/city/lights/back_4_lit_4.png"), require("../../../assets/city/lights/back_4_lit_5.png"),
];

interface Props {
    /** How far the player has run. A plain number: passing the game state object makes the
     *  React Compiler treat this as unchanged and the city stops scrolling. */
    distance: number;
    /** 0 = every window dark, 1 = fully lit. */
    lightLevel: number;
    viewWidth?: number;
    /** Called once the buildings are ready, so the start screen can appear. */
    onAssetsReady?: () => void;
}

/**
 * How much each building's lights are spread out in time. With every building following the
 * city-wide light level exactly, a whole group of windows across the city went dark at once,
 * like a power cut. Instead each building runs a little ahead of or behind the others, so the
 * lights come on - and go off, in reverse order - building by building.
 */
const STAGGER = 0.4;

/** A steady 0-1 value per building, so its timing doesn't change as it scrolls past. */
function buildingOffset(tileIndex: number, layerSeed: number) {
    const h = Math.imul((tileIndex * 31 + layerSeed) ^ 0x27d4eb2d, 0x165667b1);
    return ((h >>> 8) & 0xffff) / 0xffff;
}

/** Scatters variants along the run without an obvious 1-2-3-4 repeat. */
function variantFor(tileIndex: number) {
    const h = Math.imul(tileIndex ^ 0x9e3779b9, 0x85ebca6b);
    return ((h >>> 13) % VARIANTS + VARIANTS) % VARIANTS;
}

function tiles(
    bases: SkImage[],
    lit: SkImage[],
    { width, height, rate }: { width: number; height: number; rate: number },
    distance: number,
    viewWidth: number,
    topY: number,
    lightLevel: number,
    keyPrefix: string
) {
    if (bases.length === 0) return null;

    const worldX = distance * rate;
    const firstTile = Math.floor(worldX / width);
    const count = Math.ceil(viewWidth / width) + 2;

    // One overlay carries every window up to its level, plus the next fading in on top.
    // Scaling by LEVELS (not LEVELS - 1) means the very first group fades in from nothing
    // too: at a light level just above zero, overlay 0 is drawn at a sliver of opacity
    // rather than snapping straight to full.
    const cityLevel = Math.max(0, Math.min(1, lightLevel));
    const layerSeed = keyPrefix.length * 977;

    return Array.from({ length: count }, (_, i) => {
        const tileIndex = firstTile + i;
        // This building's own light level: the city's, shifted by its offset. At full the
        // whole city is lit and at zero it's all dark; in between, buildings differ.
        const level = Math.max(0, Math.min(1, (cityLevel - buildingOffset(tileIndex, layerSeed) * STAGGER) / (1 - STAGGER)));
        const position = level * LEVELS;
        const step = Math.min(LEVELS - 1, Math.floor(position));
        const fade = Math.min(1, position - step);
        const variant = variantFor(tileIndex) % bases.length;
        const x = tileIndex * width - worldX;
        const litIndex = variant * LEVELS;
        // Groups already fully on, then the one currently coming on.
        const established = step > 0 ? lit[litIndex + step - 1] : null;
        const arriving = fade > 0 ? lit[litIndex + step] : null;

        return (
            <React.Fragment key={`${keyPrefix}-${tileIndex}`}>
                <Image image={bases[variant]} x={x} y={topY} width={width} height={height} fit="fill" />
                {established && (
                    <Image image={established} x={x} y={topY} width={width} height={height} fit="fill" />
                )}
                {arriving && (
                    <Image image={arriving} x={x} y={topY} width={width} height={height} fit="fill" opacity={fade} />
                )}
            </React.Fragment>
        );
    });
}

export const NeonCityScenery = ({ distance, lightLevel, viewWidth: viewWidthProp, onAssetsReady }: Props) => {
    const viewWidth = viewWidthProp ?? SCREEN_WIDTH;

    const frontBase = useStripImages("city-front-base", FRONT_BASE);
    const backBase = useStripImages("city-back-base", BACK_BASE);
    const frontLit = useStripImages("city-front-lit", FRONT_LIT);
    const backLit = useStripImages("city-back-lit", BACK_LIT);

    const reported = useRef(false);
    const ready = frontBase.length > 0;
    useEffect(() => {
        if (ready && onAssetsReady && !reported.current) {
            reported.current = true;
            onAssetsReady();
        }
    }, [ready, onAssetsReady]);

    return (
        <>
            {tiles(backBase, backLit, { width: BACK_WIDTH, height: BACK_HEIGHT, rate: BACK_RATE },
                distance, viewWidth, GRID_TOP_Y - BACK_HEIGHT, lightLevel, "city-back")}
            {tiles(frontBase, frontLit, { width: FRONT_WIDTH, height: FRONT_HEIGHT, rate: FRONT_RATE },
                distance, viewWidth, GRID_TOP_Y - FRONT_HEIGHT, lightLevel, "city-front")}
        </>
    );
};
